	private static void assertCalibratedDependentPrice(boolean inclusive, double completePrice,
			CalibratedProfile profile) {
		TupleExpr source = connectedSource(2);
		PackedQuery query = PackedQueryCodec.encodeForPlanning(source);
		int count = query.relationCount();
		PackedSearchBudget budget = new PackedSearchBudget(PackedPlannerLimits.unbounded());
		PackedCostSession session = new PackedCostSession() {
			private void price(PackedCostEstimate output) {
				if (profile.component) {
					output.setComponentRows(10.0d, profile.baseWork);
				} else {
					output.setRows(10.0d, profile.baseWork);
				}
				if (inclusive) {
					output.setInclusivePhysicalCost(profile.sequential, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
							0.0d, profile.output, 0.0d, 0.0d);
				} else {
					output.setLocalPhysicalCost(profile.sequential, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
							0.0d, profile.output, 0.0d, 0.0d);
				}
				output.setInvocations(1.0d);
				if (profile.dependent) {
					output.setDependentCostComponents(profile.startup, 1.0d, 0.0d,
							profile.sequential, profile.sequential, 0.0d, 0.0d, profile.output,
							profile == CalibratedProfile.MEMOIZED ? 1.0d : 0.0d,
							0.0d, profile == CalibratedProfile.MEMOIZED ? 1.0d : 0.0d, 0.0d,
							profile == CalibratedProfile.MATERIALIZED ? 1.0d : 0.0d,
							profile == CalibratedProfile.MATERIALIZED ? 1.0d : 0.0d, profile.spill);
				}
				// The complete provider decision price may include a surcharge OR discount beyond its dimensions.
				output.setObjectiveInterval(completePrice, completePrice, completePrice);
			}

			@Override
			public void estimateLeaf(int relation, PackedCostContext context, PackedCostEstimate output) {
				if (query.relOperator(relation) == PackedRelOp.STATEMENT_PATTERN) {
					price(output);
				}
			}

			@Override
			public void appendFactor(int relation, PackedCostContext context, PackedCostEstimate output) {
				if (query.relOperator(relation) == PackedRelOp.STATEMENT_PATTERN) {
					price(output);
				}
			}

			@Override
			public void refineOperator(int relation, PackedCostContext context, PackedCostEstimate output) {
			}

			@Override
			public double objectiveScore(PackedCostEstimate estimate) {
				return Double.isFinite(estimate.objectivePoint()) ? estimate.objectivePoint() : estimate.workRows();
			}
		};
		try (PackedMemo memo = new PackedMemo(query, query.symbolCount(), count, count, 4, count, count * 2)) {
			PackedIncumbentSearch search = PackedIncumbentSearch.forSession(query, memo, budget, false, session);
			search.build();
			int winner = memo.findWinner(memo.logicalGroupId(query.rootRelId()), memo.anyPropertyId(), 0, 0, 0);
			assertTrue(winner > 0);
			assertEquals(10.0d, memo.winnerOutputRows(winner));
			assertEquals(2, memo.winnerChildCount(winner));
			for (int ordinal = 0; ordinal < 2; ordinal++) {
				int child = memo.winnerChildWinnerId(winner, ordinal);
				assertEquals(completePrice, memo.winnerTotalCost(child),
						"the actual provider certifies the complete child price");
				PackedCostEstimate stored = new PackedCostEstimate();
				memo.restorePhysicalMetadataCost(memo.winnerPhysicalMetadataId(child), stored);
				assertEquals(profile.sequential, stored.sequentialRows());
				assertEquals(profile.output, stored.resultRows());
				assertEquals(completePrice, stored.objectivePoint());
				assertEquals(1.0d, stored.invocations());
				assertEquals(inclusive ? PackedCostEstimate.CostScope.INCLUSIVE : PackedCostEstimate.CostScope.LOCAL,
						stored.costScope());
				assertEquals(profile.component, stored.hasComponentOutputRows());
				if (profile.dependent) {
					int metadata = memo.winnerPhysicalMetadataId(child);
					assertEquals(profile.startup, metadataMetric(memo, metadata, "optimizer.dependentStartupOnce"));
					assertEquals(profile.output, metadataMetric(memo, metadata, "optimizer.dependentOutputWork"));
					assertEquals(profile.spill, metadataMetric(memo, metadata, "optimizer.dependentMemorySpillWork"));
				}
			}
			// Typed startup is query-global. Whole-prefix output/spill is fixed; component output repeats.
			// The remaining COMPLETE price is per still-unpriced batch, including either sign of correction.
			observeSelectedWorkPrice(memo, winner, "calibrated:" + profile + ":" + inclusive + ":" + completePrice);
			double fixed = profile.component ? 0.0d : profile.output + profile.spill;
			double repeating = completePrice - profile.startup - fixed;
			double reopened = repeating >= 0.0d
					? profile.startup + fixed + repeating * 10.0d
					: Math.min(completePrice, 1.0d) + (completePrice - Math.min(completePrice, 1.0d)) * 10.0d;
			assertEquals(completePrice + reopened + 10.0d, memo.winnerTotalCost(winner),
					"complete price and declared global/component units must survive reopen: " + profile);
		}
	}

	private static void observeSelectedWorkPrice(PackedMemo memo, int winner, String label) {
		int physical = memo.winnerPhysicalExpressionId(winner);
		PackedCostEstimate estimate = new PackedCostEstimate();
		memo.restorePhysicalMetadataCost(memo.winnerPhysicalMetadataId(winner), estimate);
		System.out.println("SELECTED_WORK_PRICE label=" + label + " winner=" + winner
				+ " implementation=" + memo.physicalImplementationForm(physical)
				+ " physical=" + estimate.plannedStringMetric("optimizer.physicalJoinImplementation")
				+ " total=" + memo.winnerTotalCost(winner) + " rows=" + memo.winnerOutputRows(winner)
				+ " context=" + memo.winnerInputContextId(winner) + " inv=" + estimate.invocations()
				+ " point=" + estimate.objectivePoint() + " work=" + estimate.workRows()
				+ " seq=" + estimate.sequentialRows() + " result=" + estimate.resultRows()
				+ " scope=" + estimate.costScope() + " profile=" + estimate.hasDependentCostComponents());
		for (int ordinal = 0; ordinal < memo.winnerChildCount(winner); ordinal++) {
			int child = memo.winnerChildWinnerId(winner, ordinal);
			estimate.clear();
			memo.restorePhysicalMetadataCost(memo.winnerPhysicalMetadataId(child), estimate);
			System.out.println("SELECTED_WORK_CHILD label=" + label + " ordinal=" + ordinal
					+ " winner=" + child + " total=" + memo.winnerTotalCost(child)
					+ " rows=" + memo.winnerOutputRows(child) + " context=" + memo.winnerInputContextId(child)
					+ " inv=" + estimate.invocations() + " workBit=" + estimate.hasContextualScalarWork()
					+ " point=" + estimate.objectivePoint() + " scope=" + estimate.costScope()
					+ " seq=" + estimate.sequentialRows() + " result=" + estimate.resultRows()
					+ " profile=" + estimate.hasDependentCostComponents()
					+ " priced=" + estimate.dependentInvocationCount());
		}
	}

	private static double metadataMetric(PackedMemo memo, int metadata, String name) {
		for (int ordinal = 0; ordinal < memo.physicalMetadataPlannedDoubleMetricCount(metadata); ordinal++) {
			if (name.equals(memo.physicalMetadataPlannedDoubleMetricName(metadata, ordinal))) {
				return memo.physicalMetadataPlannedDoubleMetricValue(metadata, ordinal);
			}
		}
		throw new AssertionError("actual retained metadata lacks " + name);
	}

	@ParameterizedTest
	@CsvSource({ "STREAMING,false", "STREAMING,true", "MEMOIZED,false", "MEMOIZED,true",
			"MATERIALIZED,false", "MATERIALIZED,true", "COMPONENT_STREAMING,false", "COMPONENT_STREAMING,true" })
	void typedDependentProfilesSurvivePhysicalMetadataRetention(CalibratedProfile profile, boolean inclusive) {
		PackedCostEstimate source = new PackedCostEstimate();
		source.setRows(10.0d, profile.baseWork);
		if (inclusive) {
			source.setInclusivePhysicalCost(profile.sequential, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
					profile.output, 0.0d, 0.0d);
		} else {
			source.setLocalPhysicalCost(profile.sequential, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
					profile.output, 0.0d, 0.0d);
		}
		source.setDependentCostComponents(profile.startup, 1.0d, 0.0d, profile.sequential, profile.sequential,
				0.0d, 0.0d, profile.output, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, profile.spill);
		PackedPhysicalMetadataArena arena = new PackedPhysicalMetadataArena(1);
		int id = arena.append(source, source.outputRows(), source.workRows());
		assertTrue(id > 0);
		PackedCostEstimate restored = new PackedCostEstimate();
		arena.restorePhysicalCost(id, restored);
		assertEquals(source.costScope(), restored.costScope());
		assertEquals(profile.sequential, restored.sequentialRows());
		assertEquals(profile.output, restored.resultRows());
		assertTrue(restored.hasDependentCostComponents(),
				"typed startup/output/spill authority cannot be replaced by advisory display metrics");
		assertEquals(profile.startup, restored.startupOnceWork());
		assertEquals(profile.output, restored.outputWork());
		assertEquals(profile.spill, restored.memorySpillWork());
	}

	@ParameterizedTest
	@MethodSource("calibratedComponentProfiles")
	void calibratedComponentPriceRepeatsOnlyOverTwoActualUnrelatedPartitions(
			boolean inclusive, CalibratedProfile profile, double correction) {
		StatementPattern connected = pattern(-1);
		StatementPattern unrelated = new StatementPattern(Var.of("otherSubject"),
				Var.of("otherPredicate", SimpleValueFactory.getInstance().createIRI("urn:other")),
				Var.of("otherValue"));
		TupleExpr nested = connectedSource(2);
		PackedQuery query = PackedQueryCodec.encodeForPlanning(new Union(new Union(connected, unrelated), nested));
		PackedQueryView view = new PackedQueryView(query);
		int count = query.relationCount();
		PackedSearchBudget budget = new PackedSearchBudget(PackedPlannerLimits.unbounded());
		AtomicInteger actualMixedCalls = new AtomicInteger();
		double completePrice = profile.baseWork + correction;
		PackedCostSession session = new PackedCostSession() {
			private void physical(PackedCostEstimate output, double invocations) {
				if (inclusive) {
					output.setInclusivePhysicalCost(profile.sequential, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
							profile.output, 0.0d, 0.0d);
				} else {
					output.setLocalPhysicalCost(profile.sequential, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
							profile.output, 0.0d, 0.0d);
				}
				output.setInvocations(invocations);
				if (profile.dependent) {
					output.setDependentCostComponents(profile.startup, invocations, 0.0d,
							profile.sequential, profile.sequential, 0.0d, 0.0d, profile.output,
							0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
				}
				output.setObjectiveInterval(completePrice, completePrice, completePrice);
			}

			@Override
			public void estimateLeaf(int relation, PackedCostContext context, PackedCostEstimate output) {
				output.setRows(10.0d, profile.baseWork);
				physical(output, 1.0d);
			}

			@Override
			public void appendFactor(int relation, PackedCostContext context, PackedCostEstimate output) {
				double unrelatedRows = context.unrelatedPrefixRows();
				double component = Double.isFinite(unrelatedRows) && unrelatedRows > 0.0d
						? context.prefixRows() / unrelatedRows
						: context.prefixRows();
				output.setComponentRows(component, profile.baseWork);
				physical(output, component);
				if (unrelatedRows == 2.0d) {
					actualMixedCalls.incrementAndGet();
					assertEquals(10.0d, component);
					assertTrue(output.hasComponentOutputRows());
					assertEquals(10.0d, output.invocations());
				}
			}

			@Override
			public void refineOperator(int relation, PackedCostContext context, PackedCostEstimate output) {
			}

			@Override
			public double objectiveScore(PackedCostEstimate estimate) {
				return Double.isFinite(estimate.objectivePoint()) ? estimate.objectivePoint() : estimate.workRows();
			}
		};
		try (PackedMemo memo = new PackedMemo(query, query.symbolCount(), count, count, 4, count, count * 2)) {
			PackedIncumbentSearch search = PackedIncumbentSearch.forSession(query, memo, budget, false, session);
			search.build();
			PackedJoinEnumerator enumerator = PackedJoinEnumerator.forSession(query, memo,
					search.selectedRowsByGroup(), budget, session);
			int winner = enumerator.optimizeWithInheritedPrefix(relationId(view, nested),
					new int[] { relationId(view, connected), relationId(view, unrelated) },
					new double[] { 10.0d, 2.0d }, 2, 20.0d);
			assertTrue(winner > 0);
			assertTrue(actualMixedCalls.get() > 0,
					"actual callback must receive R20/C10/U2 before claiming a component hit");
			assertTrue(memo.winnerInputContextId(winner) > 0);
			assertEquals(20.0d, memo.winnerOutputRows(winner));
			double repeated = profile.startup + (completePrice - profile.startup) * 2.0d;
			assertEquals(2.0d * repeated + 2.0d * 20.0d, memo.winnerTotalCost(winner),
					"component result work and signed correction repeat over U2; declared startup remains once");
		}
	}

	private static Stream<Arguments> calibratedComponentProfiles() {
		return Stream.of(CalibratedProfile.COMPONENT, CalibratedProfile.COMPONENT_STREAMING)
				.flatMap(profile -> Stream.of(false, true)
						.flatMap(inclusive -> Stream.of(-3.0d, 0.0d, 3.0d)
								.map(correction -> Arguments.of(inclusive, profile, correction))));
	}

	private enum CalibratedProfile {
		SCAN(10.0d, 10.0d, 0.0d, 0.0d, 0.0d, false, false),
		PHYSICAL_FIXED(8.0d, 6.0d, 0.0d, 2.0d, 0.0d, false, false),
		STREAMING(10.0d, 6.0d, 2.0d, 2.0d, 0.0d, true, false),
		MEMOIZED(10.0d, 6.0d, 2.0d, 2.0d, 0.0d, true, false),
		MATERIALIZED(10.0d, 6.0d, 2.0d, 1.0d, 1.0d, true, false),
		COMPONENT(8.0d, 6.0d, 0.0d, 2.0d, 0.0d, false, true),
		COMPONENT_STREAMING(10.0d, 6.0d, 2.0d, 2.0d, 0.0d, true, true);

		final double baseWork;
		final double sequential;
		final double startup;
		final double output;
		final double spill;
		final boolean dependent;
		final boolean component;

		CalibratedProfile(double baseWork, double sequential, double startup, double output, double spill,
				boolean dependent, boolean component) {
			this.baseWork = baseWork;
			this.sequential = sequential;
			this.startup = startup;
			this.output = output;
			this.spill = spill;
			this.dependent = dependent;
			this.component = component;
		}
	}

	private static PackedCostModel prefixModel(Price price) {
		return new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return query.isStatementPattern(relationId) ? 10.0d : Double.NaN;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {
					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						priceLeaf(price, output);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (price == Price.ISOLATED_SCALAR) {
							return;
						}
						if (price == Price.ISOLATED_EXPLICIT || price == Price.ISOLATED_INCLUSIVE) {
							priceLeaf(price, output);
							return;
						}
						double rows = context.prefixRows();
						if (price == Price.COMPONENT_SCALAR || price == Price.COMPONENT_EXPLICIT) {
							double unrelated = context.unrelatedPrefixRows();
							rows = Double.isFinite(unrelated) && unrelated > 0.0d ? rows / unrelated : rows;
							output.setComponentRows(rows, rows);
							output.setInvocations(rows);
						} else {
							output.setContextualRows(rows, rows);
						}
						if (price == Price.CONTEXTUAL_INCLUSIVE) {
							output.setInclusivePhysicalCost(rows, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
									0.0d, 0.0d, 0.0d);
							output.setInvocations(rows);
						} else if (price == Price.CONTEXTUAL_EXPLICIT || price == Price.COMPONENT_EXPLICIT) {
							output.setLocalPhysicalCost(rows, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
									0.0d, 0.0d, 0.0d);
							output.setInvocations(rows);
						}
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
					}
				};
			}
		};
	}

	private static int relationId(PackedQueryView query, TupleExpr expression) {
		int found = 0;
		for (int relation = 1; relation <= query.relationCount(); relation++) {
			if (query.materializeRelation(relation).equals(expression)) {
				assertEquals(0, found, "the fixture expression has one actual occurrence");
				found = relation;
			}
		}
		assertTrue(found > 0);
		return found;
	}

	private static TupleExpr connectedSource(int factorCount) {
		TupleExpr source = pattern(0);
		for (int factor = 1; factor < factorCount; factor++) {
			source = new Join(source, pattern(factor));
		}
		return source;
	}

	private static StatementPattern pattern(int factor) {
		return new StatementPattern(Var.of("subject"),
				Var.of("predicate" + factor, SimpleValueFactory.getInstance().createIRI("urn:price:" + factor)),
				Var.of("value" + factor));
	}

	private enum Price {
		ISOLATED_SCALAR,
		CONTEXTUAL_SCALAR,
		ISOLATED_EXPLICIT,
		CONTEXTUAL_EXPLICIT,
		ISOLATED_INCLUSIVE,
		CONTEXTUAL_INCLUSIVE,
		COMPONENT_SCALAR,
		COMPONENT_EXPLICIT
	}

	@ParameterizedTest
	@CsvSource({ "false,PHYSICAL_FIXED", "true,PHYSICAL_FIXED", "false,STREAMING", "true,STREAMING",
			"false,MEMOIZED", "true,MEMOIZED", "false,MATERIALIZED", "true,MATERIALIZED" })
	void positiveWholePriceSurvivesAnUnqualifiedFixedComponentDecomposition(boolean inclusive,
			CalibratedProfile profile) {
		assertTrue(profile.startup + profile.output + profile.spill > 1.0d);
		assertCalibratedDependentPrice(inclusive, 1.0d, profile);
	}

	@ParameterizedTest
	@CsvSource({ "unary-metadata,false", "unary-metadata,true", "binary-metadata,false",
			"binary-metadata,true", "binary-estimate,false", "binary-estimate,true" })
	void bareChildVectorCannotCertifyItsInvocationDomain(String route, boolean component) {
		PackedQuery query = PackedQueryCodec.encodeForPlanning(connectedSource(2));
		int count = query.relationCount();
		try (PackedMemo memo = new PackedMemo(query, query.symbolCount(), count, count, 4, count, count * 2)) {
			PackedCostEstimate child = new PackedCostEstimate();
			if (component) {
				child.setComponentRows(5.0d, 10.0d);
			} else {
				child.setContextualRows(5.0d, 10.0d);
			}
			child.setLocalPhysicalCost(10.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
			child.setInvocations(10.0d);
			assertTrue(child.hasContextualOutputRows());
			assertEquals(component, child.hasComponentOutputRows());
			assertEquals(10.0d, child.invocations());
			int childVector = memo.physicalCostVectorId(child);
			assertTrue(childVector > 0);
			PackedCostEstimate independent = new PackedCostEstimate();
			independent.setRows(5.0d, 10.0d);
			independent.setLocalPhysicalCost(10.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
			assertEquals(1.0d, independent.invocations());
			int independentVector = memo.physicalCostVectorId(independent);
			assertEquals(independentVector, childVector,
					"the current bare vector representation does not retain invocation/frame qualification");
			PackedCostEstimate parent = new PackedCostEstimate();
			parent.setRows(5.0d, 1.0d);
			parent.setLocalPhysicalCost(1.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
			assertFalse(parent.hasContextualOutputRows());
			assertEquals(1.0d, parent.invocations());
			int metadata = memo.addPhysicalMetadata(parent, parent.outputRows(), parent.workRows());
			assertTrue(metadata > 0);
			int complete = switch (route) {
			case "unary-metadata" -> memo.completeUnaryPhysicalCostVectorId(metadata, childVector);
			case "binary-metadata" -> memo.completeBinaryPhysicalCostVectorId(metadata, childVector, independentVector);
			case "binary-estimate" -> memo.completeBinaryPhysicalCostVectorId(parent, childVector, independentVector);
			default -> throw new AssertionError(route);
			};
			assertTrue(complete == 0 || !memo.costVectors()
					.isKnown(complete,
							PackedCostDimensionRegistry.SOURCE_ROW_EVENTS),
					"a default LOCAL parent cannot authenticate a child's domain from the parent's own flags");
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "metadata", "trace" })
	void untypedRestoreAfterDeclaredScratchResetDoesNotResurrectATypedProfile(String route) {
		PackedCostEstimate source = new PackedCostEstimate();
		source.setRows(10.0d, 10.0d);
		assertFalse(source.hasDependentCostComponents());
		PackedCostEstimate destination = new PackedCostEstimate();
		destination.setRows(10.0d, 10.0d);
		destination.setDependentCostComponents(2.0d, 1.0d, 0.0d, 3.0d, 3.0d, 0.0d, 0.0d,
				1.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
		assertTrue(destination.hasDependentCostComponents());
		// Match the production restoreWinnerEstimate scratch-reset contract.
		destination.clear();
		assertFalse(destination.hasDependentCostComponents());
		if (route.equals("metadata")) {
			PackedPhysicalMetadataArena arena = new PackedPhysicalMetadataArena(1);
			int id = arena.append(source, source.outputRows(), source.workRows());
			assertTrue(id > 0);
			arena.restorePhysicalCost(id, destination);
		} else {
			PackedCostContext context = new PackedCostContext();
			context.reset(new int[] { 1 }, 0, 1, 10.0d);
			PackedCostingTraceArena arena = new PackedCostingTraceArena();
			int id = arena.append(PackedCostingPhase.PREFIX_EXTENSION, 2, context, 0, context,
					source, source, source.workRows());
			assertTrue(id > 0);
			arena.restore(id, destination);
		}
		assertFalse(destination.hasDependentCostComponents(),
				"documented scratch reset must prevent typed profile resurrection: " + route);
	}

