	@ParameterizedTest
	@ValueSource(strings = { "default", "inherited", "component" })
	void retainedCandidateUsesActualChildDomainBeforeComposingLocalResources(String route) {
		StatementPattern outer = pattern(-1);
		StatementPattern inner = pattern(0);
		Projection projection = new Projection(inner,
				new ProjectionElemList(new ProjectionElem("subject"), new ProjectionElem("value0")), false);
		PackedQuery query = PackedQueryCodec.encodeForPlanning(new Union(outer, projection));
		PackedQueryView view = new PackedQueryView(query);
		int count = query.relationCount();
		try (PackedMemo memo = new PackedMemo(query, query.symbolCount(), count, count, 4, count, count * 2)) {
			int property = memo.anyPropertyId();
			int childRelation = relationId(view, inner);
			int childGroup = memo.logicalGroupId(childRelation);
			int childPhysical = memo.addPhysicalAlternative(childGroup, PackedRelOp.STATEMENT_PATTERN,
					query.relPayload(childRelation), property, 7, new int[0], 0, 0);
			PackedCostEstimate child = new PackedCostEstimate();
			if (route.equals("component")) {
				child.setComponentRows(5.0d, 5.0d);
			} else if (route.equals("inherited")) {
				child.setContextualRows(5.0d, 5.0d);
			} else {
				child.setRows(5.0d, 5.0d);
			}
			child.setLocalPhysicalCost(5.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
			child.setInvocations(route.equals("default") ? 1.0d : 10.0d);
			int childContext = 0;
			if (route.equals("inherited")) {
				int outerRelation = relationId(view, outer);
				childContext = memo.internEvidenceContext(new int[] { outerRelation }, null, 0, 1, 10.0d, 0,
						query.relAssuredMaskId(outerRelation), 0, 0, 0);
				assertTrue(childContext > 0);
			}
			int childMetadata = memo.addPhysicalMetadata(child, 5.0d, 5.0d);
			assertTrue(childMetadata > 0);
			int childWinner = memo.offerWinnerWithMetadata(childGroup, property, 0, childContext, 0,
					childPhysical, childMetadata, 0.0d, 5.0d, 5.0d, new int[0], 0, 0);
			assertTrue(childWinner > 0);
			assertEquals(childContext, memo.winnerInputContextId(childWinner));
			int rootRelation = relationId(view, projection);
			int rootGroup = memo.logicalGroupId(rootRelation);
			int physical = memo.addPhysicalAlternative(rootGroup, PackedRelOp.PROJECTION,
					query.relPayload(rootRelation),
					property, 8, new int[] { childGroup }, 0, 1);
			PackedCostEstimate local = new PackedCostEstimate();
			local.setRows(5.0d, 2.0d);
			local.setLocalPhysicalCost(2.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
			int metadata = memo.addPhysicalMetadata(local, 5.0d, 2.0d);
			assertTrue(metadata > 0);
			int winner = memo.offerWinnerWithMetadata(rootGroup, property, 0, 0, 0, physical,
					metadata, 0.0d, 7.0d, 7.0d, new int[] { childWinner }, 0, 1);
			assertTrue(winner > 0);
			assertEquals(7.0d, memo.winnerTotalCost(winner),
					"supplied complete price is independent of vector availability");
			int vector = memo.winnerCostVectorId(winner);
			assertTrue(vector > 0, "the supplied scalar candidate remains executable/retained");
			assertEquals(route.equals("default"),
					memo.costVectors().isKnown(vector, PackedCostDimensionRegistry.SOURCE_ROW_EVENTS),
					"candidate composition must inspect its actual child frame/units: " + route);
			if (route.equals("default")) {
				assertEquals(7.0d, memo.costVectors().point(vector, PackedCostDimensionRegistry.SOURCE_ROW_EVENTS));
			}
		}
	}

