	@ParameterizedTest
	@CsvSource({ "0,0", "0,1", "1,0", "1,1", "10,0", "10,1", "10,10", "1000,1", "1000,1000" })
	void coldMemoizedDemandHasNoPositiveInputZeroMissState(double leftRows, double distinct) {
		PackedCostContext context = new PackedCostContext();
		context.setOperatorInputs(leftRows, 1_000.0d);
		PackedCostEstimate output = new PackedCostEstimate();
		output.setRows(leftRows, 0.0d);
		output.putPlannedDoubleMetric(PackedPhysicalJoinCosting.MEMOIZED_DEPENDENT_RIGHT_ROWS_METRIC, 1_000.0d);
		output.putPlannedDoubleMetric(PackedPhysicalJoinCosting.MEMOIZED_DEPENDENT_RIGHT_WORK_METRIC, 100_000.0d);
		output.putPlannedDoubleMetric(PackedPhysicalJoinCosting.MEMOIZED_DISTINCT_KEYS_METRIC, distinct);
		PackedPhysicalJoinCosting.refine(emptySession(), PackedPhysicalJoinCosting.MEMOIZED_CORRELATED,
				context, output);
		double misses = output.plannedDoubleMetric(PackedPhysicalJoinCosting.MEMOIZED_CACHE_MISSES_METRIC, Double.NaN);
		if (leftRows == 0.0d) {
			assertEquals(0.0d, misses);
			assertEquals(0.0d, output.peakMemoryRows());
			assertEquals(0.0d, output.workRows());
		} else {
			assertTrue(misses > 0.0d, "a fresh nonempty invocation cannot have zero misses");
			assertTrue(misses >= Math.min(leftRows, distinct));
		}
	}

	@Test
	void veryLargeFiniteColdInvocationKeepsItsOneUnavoidableCacheMiss() {
		double leftRows = Math.scalb(1.0d, 54);
		PackedCostContext context = new PackedCostContext();
		context.setOperatorInputs(leftRows, 1_000.0d);
		PackedCostEstimate output = new PackedCostEstimate();
		output.setRows(leftRows, 0.0d);
		output.putPlannedDoubleMetric(PackedPhysicalJoinCosting.MEMOIZED_DEPENDENT_RIGHT_ROWS_METRIC, 1_000.0d);
		output.putPlannedDoubleMetric(PackedPhysicalJoinCosting.MEMOIZED_DEPENDENT_RIGHT_WORK_METRIC, 100_000.0d);
		output.putPlannedDoubleMetric(PackedPhysicalJoinCosting.MEMOIZED_DISTINCT_KEYS_METRIC, 1.0d);
		PackedPhysicalJoinCosting.refine(emptySession(), PackedPhysicalJoinCosting.MEMOIZED_CORRELATED, context,
				output);
		double misses = output.plannedDoubleMetric(PackedPhysicalJoinCosting.MEMOIZED_CACHE_MISSES_METRIC, Double.NaN);
		assertEquals(1.0d, misses,
				"the same cold-cache formula must retain its mandatory first miss at finite leftRows="
						+ leftRows + ", actual hits="
						+ output.plannedDoubleMetric(PackedPhysicalJoinCosting.MEMOIZED_CACHE_HITS_METRIC, Double.NaN));
	}

	@Test
	void zeroLeftMemoizedCandidateDoesNotRetainAuthenticatedRightStartupOrPeak() {
		LeftJoin source = new LeftJoin(pattern(0), pattern(1));
		AtomicInteger contextualRight = new AtomicInteger();
		AtomicInteger memoized = new AtomicInteger();
		PackedCostModel model = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relation) {
				return query.isStatementPattern(relation)
						? query.statementPatternValue(relation, 1).stringValue().equals("urn:price:0")
								? 0.0d
								: 1_000_000.0d
						: Double.NaN;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {
					@Override
					public void estimateLeaf(int relation, PackedCostContext context, PackedCostEstimate output) {
						double rows = estimateRows(query, relation);
						if (Double.isFinite(rows)) {
							output.setRows(rows, rows);
						}
					}

					@Override
					public void appendFactor(int relation, PackedCostContext context, PackedCostEstimate output) {
						assertEquals(0.0d, context.prefixRows());
						contextualRight.incrementAndGet();
						output.setContextualRows(0.0d, 110_000.0d);
						output.setInclusivePhysicalCost(100_000.0d, 2_000.0d, 3_000.0d, 4_000.0d,
								5_000.0d, 6_000.0d, 7_000.0d, 8_000.0d, 9_000.0d, 10_000.0d);
						output.setInvocations(0.0d);
						output.setDependentCostComponents(20_000.0d, 0.0d, 0.0d, 80.0d, 80.0d,
								0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 10_000.0d);
						output.setObjectiveInterval(110_000.0d, 110_000.0d, 110_000.0d);
					}

					@Override
					public void refineOperator(int relation, PackedCostContext context, PackedCostEstimate output) {
						if (query.operatorTag(relation) == PackedRelOp.LEFT_JOIN) {
							output.setOutputRowsPreservingPhysicalCost(0.0d);
							output.putPlannedDoubleMetric(PackedPhysicalJoinCosting.MEMOIZED_DISTINCT_KEYS_METRIC,
									0.0d);
						}
					}

					@Override
					public void refineIntermediateJoin(PackedCostContext context, PackedCostEstimate output) {
						if ("memoized-correlated"
								.equals(output.plannedStringMetric("optimizer.physicalJoinImplementation"))) {
							memoized.incrementAndGet();
							assertEquals(0.0d, output.outputRows());
							assertEquals(0.0d, output.workRows());
							assertEquals(0.0d, output.sequentialRows());
							assertEquals(0.0d, output.peakMemoryRows(), "no RHS demand means no retained RHS memory");
							assertEquals(0.0d, output.plannedDoubleMetric(
									PackedPhysicalJoinCosting.MEMOIZED_CACHE_MISSES_METRIC, Double.NaN));
						}
					}

					@Override
					public double objectiveScore(PackedCostEstimate output) {
						return output.objectivePoint();
					}
				};
			}
		};
		PackedPlanningResult result = PackedCascadesPlanner.optimize(source,
				OptimizationGoal.root(source, PhysicalProperties.ANY), model);
		assertTrue(result.exactComplete());
		assertTrue(contextualRight.get() > 0, "the existing producer must supply its actual RHS metadata");
		assertTrue(memoized.get() > 0, "the normal ANY search must offer the memoized physical implementation");
		assertEquals(0.0d, result.outputRows());
	}

	@Test
	void independentlyPricedObjectivePointSurvivesActualRecipeReplay() {
		PackedCostEstimate supplied = new PackedCostEstimate();
		supplied.setRows(10.0d, 7.0d);
		supplied.setObjectiveInterval(100.0d, 123.0d, 150.0d);
		PackedCostEstimate restored = replayUnknownResourceRecipe(supplied);
		assertEquals(7.0d, restored.workRows(), "raw storage must not replace either independent quantity");
		assertEquals(123.0d, restored.objectivePoint());
		assertEquals(100.0d, restored.objectiveLower());
		assertEquals(150.0d, restored.objectiveUpper());
	}

